package com.ecopulse.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List; @Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtFilter(JwtService jwt){this.jwt=jwt;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{ String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){ try{ String email=jwt.subject(h.substring(7)); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(email,null,List.of())); }catch(Exception ignored){} } c.doFilter(r,s); } }
